def compute_c_n(n, m, bunch):
    # Time step.
    dt = bunch[0][1] - bunch[0][0]
    return np.sum(bunch[1, :]*polynomial(n, m, bunch[0, :]))*dt


def compute_coeff(i, j, m, t):
    # Time step.
    dt = t[1] - t[0]
    coeff = \
            np.sum(polynomial(i, m, t[:])*polynomial(j, m, t[:]) \
            *Gaussian(m[1], m[2], t[:]))*dt
    return coeff


def compute_distr(c_n, N_n, m, t, with_Gaussian):
    n = len(t)
    bunch = np.zeros(n)
    for j in range(n):
        bunch[j] = 0e0
        for k in range(len(c_n)):
            bunch[j] += c_n[k]*polynomial(k, m, t[j])/N_n[k]
        if with_Gaussian:
            bunch[j] *= Gaussian(m[1], m[2], t[j])
    return np.array([t, bunch])


def check_basis(n):
    print()
    for i in range(0, n+1):
        for j in range(0, n+1):
            coeff = compute_coeff(i, j, m, bunch_first[0])
            print(f"c_{i:d}{j:d} = {coeff:10.3e}")


def compute_residual(m, bunch):
    bunch[1, :] /= Gaussian(m[1], m[2], bunch[0, :])
    return bunch


def wrt_csv_file(file_name, bunch):
    np.savetxt(file_name, bunch, fmt="%.18e", delimiter=" ", newline='\n')


file_dir = os.path.join(
    os.environ["HOME"], "/Volumes/Ext. HD (Dropbox)", "Dropbox",
    "collective-effects-tracking", "TO", "examples-profiles")
if True:
    file_name = os.path.join(file_dir, "profiles_complexFF_173bunches.csv")
    bunch_first  = rd_csv_file(file_name, 173)
    bunch_middle = rd_csv_file(file_name, 88)
    bunch_last   = rd_csv_file(file_name, 1)
else:
    file_name = os.path.join(file_dir, "profiles_complexFF_164bunches.csv")
    bunch_first  = rd_csv_file(file_name, 164)
    bunch_middle = rd_csv_file(file_name, 82)
    bunch_last   = rd_csv_file(file_name, 1)

bunch = bunch_first

m_1 = compute_moment(1, bunch)
