print("\n[mean, sigma, sigma^2] = [{:9.3e}, {:9.3e}, {:9.3e}]".
      format(m_1, np.sqrt(m_2), m_2))
# Moments for a Gaussian.
print(f"For a Gaussion m_4 = 3 m_2^2 = {3e0*m_2**2:9.3e}")
m = np.array([
    0e0, m_1, m_2, 0e0, 3e0*m_2**2, 0e0, 15e0*m_2**3, 0e0, 105*m_2**4, 0e0,
    945*m_2**5, 0e0, 10395*m_2**6, 0e0, 135135*m_2**7, 0e0, 2027025*m_2**8,
    0e0, 34459425*m_2**9, 0e0
])

c_max = 6

if False:
    check_basis(c_max)

c = np.zeros(c_max+1)
N = np.zeros(c_max+1)
N_ref = np.array([
    1e0, m[2], 2e0*m[2]**4, 24e0*m[2]**9, 3456e0*m[2]**16, 9953280*m[2]**25,
    859963392000*m[2]**36, 3120635156889600000*m[2]**49,
    56987379759357320232960000000*m[2]**63,
    50891154809600070901039104000000000*m[2]**79 \
    *(10382561 + 25*m[2]*(9094274 + 41409225*m[2]))
])
print()
for k in range(0, c_max+1):
    c[k] = compute_c_n(k, m, bunch)
    N[k] = compute_coeff(k, k, m, bunch[0])
    print("c_{:d} = {:10.3e} N_{:d} = {:10.3e} ({:9.3e}) ratio = {:10.3e}".
          format(k, c[k], k, N[k], N_ref[k], c[k]/N[k]))

